<h1 class="text-3xl font-bold mb-6">Usuarios</h1><form method="post" class="grid md:grid-cols-4 gap-3 bg-slate-900 p-4 rounded-xl mb-6"><?=$csrf->field()?><input class="bg-slate-800 p-3 rounded" name="name" placeholder="Nombre" required><input class="bg-slate-800 p-3 rounded" name="email" type="email" placeholder="Correo" required><input class="bg-slate-800 p-3 rounded" name="password" type="password" minlength="12" placeholder="Contraseña (12+)" required><button class="bg-cyan-600 rounded">Crear</button></form><div class="overflow-auto"><table class="w-full"><thead><tr class="text-left text-slate-400"><th>ID</th><th>Nombre</th><th>Correo</th><th>Estado</th></tr></thead><tbody><?php foreach($users as $u):?><tr class="border-t border-slate-800"><td class="py-3"><?=$u['id']?></td><td><?=htmlspecialchars($u['name'])?></td><td><?=htmlspecialchars($u['email'])?></td><td><?=htmlspecialchars($u['status'])?></td></tr><?php endforeach?></tbody></table></div>
